/** @typedef {{slug:string,title:string,description:string,example:string,howTo:string,limitations:string,category:string,mode:string}} FreeTool */
/** @type {FreeTool[]} */
export const tools = rows.map(([slug, title, description, example, howTo, limitations, category, mode]) => ({
  slug, title, description, example, howTo, limitations, category, mode: mode ?? "text",
}));

export const categories = ["Agents", "Developer", "SEO", "Writing", "PDF", "Image", "Audio", "Collaboration"];
export function getTool(slug) { return tools.find((tool) => tool.slug === slug) ?? null; }
